effect.shader:
void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    vec3 fundo = orig.rgb;

    float y = acScreenNorm.y;
    float x = acScreenNorm.x;

    if (y < horizon) {
        // céu
        float grad = smoothstep(0.0, horizon, y);
        vec3 ceu = mix(skyColor.rgb * 0.5, skyColor.rgb, grad);
        fundo = mix(fundo, ceu, (1.0 - orig.a) * skyColor.a);
    } else {
        // chão em perspectiva
        float z = (y - horizon) / (1.0 - horizon);
        float profundidade = 1.0 / max(z, 1e-3);
        float linhaY = fract((profundidade * 0.5) - acTime * speed * 2.0);
        float lY = smoothstep(0.03, 0.0, abs(linhaY - 0.5) - 0.48);
        float linhaX = fract((x - 0.5) * density * profundidade * 0.25);
        float lX = smoothstep(0.03, 0.0, abs(linhaX - 0.5) - 0.48);
        float grid = max(lX, lY);
        vec3 grade = mix(skyColor.rgb * 0.3, lineColor.rgb, grid * lineColor.a);
        fundo = mix(fundo, grade, (1.0 - orig.a) * intensity);
    }
    fragColor = vec4(fundo * (1.0 - orig.a) + orig.rgb * orig.a, max(orig.a, intensity * 0.5));
}
